  ui_story_5003_50030201_21_dialog_content = "Disculpe, señora, ¿también es usted del continente de Astra?",
  ui_story_5003_50030201_22_dialog_content = "No, yo nací y crecí aquí en Montaña Nube.",
  ui_story_5003_50030201_23_dialog_content = "¿Sabe quiénes somos?",
  ui_story_5003_50030201_24_dialog_content = "Esta es la primera vez que nos vemos.",
  ui_story_5003_50030201_25_dialog_content = "¡Grandioso! ¡Parece que eres un local a pesar de tu fluidez en Universés!",
  ui_story_5003_50030201_26_dialog_content = "Jaja, eres gracioso.",
  ui_story_5003_50030201_27_dialog_content = "Lo siento, esta es nuestra prim. vez aquí. No estamos muy familiarizados con este lugar, por lo que es posible que hayamos hecho dem. preguntas.",
