  ui_story_5003_50030201_29_dialog_content = "Bueno, ¿podemos preguntarle algo sobre el Sakae Dojo?",
  ui_story_5003_50030201_30_dialog_content = "¿El Sakae Dojo? ¿Quién eres tú?",
  ui_story_5003_50030201_31_dialog_content = "No importa quien soy. Escuché que este lugar era originalmente un dojo... y sentí un poco de curiosidad.",
  ui_story_5003_50030201_32_dialog_content = "Lo siento, querido huésped, aunque dirijo el hotel...",
  ui_story_5003_50030201_33_dialog_content = "En realidad, no soy la dueña y no sé mucho sobre ese dojo.",
  ui_story_5003_50030201_34_dialog_content = "Cuando llegué aquí, el dojo ya había desaparecido, dejando solo un trozo de terreno abierto.",
  ui_story_5003_50030201_35_dialog_content = "Mi querida invitada, ¿podría saber tu nombre?",
  ui_story_5003_50030201_36_dialog_content = "Puedo preguntarles por ti. Si surge algo, te lo haré saber.",
