  ui_story_5003_50030201_38_dialog_content = "Hiiro... Qué nombre tan maravilloso.",
  ui_story_5003_50030201_39_dialog_content = "Tweety, ¿has regis. a nuestros huéspedes y les has preg. cuánto tiempo planean quedarse?",
  ui_story_5003_50030201_40_dialog_content = "¡Todos se degis. por tdes días!",
  ui_story_5003_50030201_41_dialog_content = "Está bien. Esperemos que nuestros huéspedes puedan man. un perfil bajo durante los próx. tres días...",
  ui_story_5003_50030201_42_dialog_content = "Le aseguro que <color=#FFB400>no moles. a nadie ajeno a este asunto</color>.",
  ui_story_5003_50030201_43_dialog_content = "Además, por favor no digan que estamos aquí.",
  ui_story_5003_50030201_44_dialog_content = "Por supuesto, nunca revelamos la info. de nuestros huéspedes a nadie. Puedes estar segura.",
  ui_story_5003_50030201_45_dialog_content = "También puedes ir a Calle Spa y preguntar por allí. Quizá encuentres la información que buscas.",
  ui_story_5003_50030201_46_dialog_content = "Caminamos por la calle todo el día pero no enc. nada...",
  ui_story_5003_50030201_47_dialog_content = "Comandante Hiiro, ¿deberíamos regresar y desc. antes de continuar?",
  ui_story_5003_50030201_48_dialog_content = "De lo contrario, podría haber otra situación como esta mañana...",
  ui_story_5003_50030201_49_dialog_content = "¿Te preocupa que si me enfrento a otro desafío en mi condición actual, pueda volver a perder?",
  ui_story_5003_50030201_50_dialog_content = "Lo siento.",
  ui_story_5003_50030201_51_dialog_content = "No, no... No hay debes disculparte. Tenías razón en preocuparte. Regresemos y descansemos bien hoy.",
  ui_story_5003_50030201_52_dialog_content = "Eso es una \"fuente termal\" para ti. Parece tener propiedades rejuvenecedoras.",
  ui_story_5003_50030201_53_dialog_content = "¿No es la temperatura diferente a lo que dijo antes Vice? Me siento un poco mareado...",
  ui_story_5003_50030201_54_dialog_content = "¿No acabas de llegar a la primavera?",
  ui_story_5003_50030201_55_dialog_content = "Sí... Siempre tomo baños muy rápidos.",
  ui_story_5003_50030201_56_dialog_content = "¡Ah, espera! ¿No eres tú el de antes? ¡El que de repente inició <color=#FFB400>un duelo con Hiiro</color>!",
  ui_story_5003_50030201_57_dialog_content = "¿Te refieres a la de cabello rosado?",
  ui_story_5003_50030201_58_dialog_content = "¿Qué estás haciendo aquí? ¿Qué quieres?",
  ui_story_5003_50030201_59_dialog_content = "Se llama <color=#FFB400>\"combate\"</color>, no \"duelo.\" ¿De verdad debes tenerme tanto miedo?",
  ui_story_5003_50030201_60_dialog_content = "No me enc. a menudo con compañeros discípulos. Es natural que debamos entrenar ... ¿y no estaba de acuerdo con eso Hiiro?",
  ui_story_5003_50030201_61_dialog_content = "¿Eh? Supongo que... ¿tiene algún sentido?",
  ui_story_5003_50030201_62_dialog_content = "Vice, no juegues con la yukata.",
  ui_story_5003_50030201_63_dialog_content = "¡Deberías relajarte de vez en cuando, Comandante Hiiro! ¡No seas tan tensa!",
  ui_story_5003_50030201_64_dialog_content = "¿Son esas... voces viniendo del baño de mujeres? Parece que este lugar no está muy insonorizado...",
  ui_story_5003_50030201_65_dialog_content = "Para nada...",
  ui_story_5003_50030201_66_dialog_content = "Entonces hablemos en otro lugar.",
  ui_story_5003_50030201_67_dialog_content = "Hab. de eso, Comandante Hiiro es como una flor de cerezo.",
  ui_story_5003_50030201_68_dialog_content = "¡Estoy de acuedo! ¡Hiido es como dijiste!",
  ui_story_5003_50030201_69_dialog_content = "Tal vez sea porque soy miembro de la <color=#FFB400>Familia Sakura</color>.",
  ui_story_5003_50030201_70_dialog_content = "¿La famidia Sakuda? Lo edscuché de Abuedita. Esa es una familia <color=#FFB400>misteriosa y poderosa</color>.",
  ui_story_5003_50030201_71_dialog_content = "Pedo los Sakudas son... ¿No desapadeciedon hace mucho tiempo?",
  ui_story_5003_50030201_72_dialog_content = "En efecto. Desaparecieron hace mucho tiempo... El tiempo de los Sakura fue breve, pero enfre. la muerte con inquebrantable valentía.",
  ui_story_5003_50030201_73_dialog_content = "Yo ya era la última de mi línea mucho antes de alc. la mayoría de edad.",
  ui_story_5003_50030201_74_dialog_content = "Do siento... No quise tdaer una memodia tan tdiste...",
  ui_story_5003_50030201_75_dialog_content = "No te preocupes. No es un recuerdo partic. triste para mí.",
  ui_story_5003_50030201_76_dialog_content = "Fui criada por mi maestro, así que recuerdo mucho sobre la Familia Sakura.",
  ui_story_5003_50030201_77_dialog_content = "Mi maestro es lo más parecido a una familia para mí... Así que no estoy muy preocupada por mi familia biológica.",
  ui_story_5003_50030201_78_dialog_content = "Además, poder regresar a mi ciudad natal así y ver las flores de cerezo aquí es lo sufi. bueno para mí.",
  ui_story_5003_50030201_79_dialog_content = "Lo siento, pensé que nos seguiste al hotel.",
  ui_story_5003_50030201_80_dialog_content = "Pero ahora que lo pienso, estás usando un yukata... Ent. debes ser un invitado aquí.",
  ui_story_5003_50030201_81_dialog_content = "Sí. Pero para ser precisos, soy un inversor en este hotel. Aquí está mi tarjeta de pres.",
  ui_story_5003_50030201_82_dialog_content = "¿Eres uno de los inversores del hotel? ¿Pero tu tarjeta de pres. dice que trabajas en Umbraton?",
  ui_story_5003_50030201_83_dialog_content = "Puedes llamarme Taki. Tengo una empresa en Umbraton. Puedes venir a busc. si alguna vez tienes negocios allí en el futuro.",
  ui_story_5003_50030201_84_dialog_content = "Me sorprendió lo suf. saber que Tweety es de Unión de Mensajería, y ahora tu eres de Astra.",
  ui_story_5003_50030201_X84_dialog_content = "Pero ahora, de repente, siento que conocer gente de algún lugar familiar es bastante reconfortante.",
  ui_story_5003_50030201_85_dialog_content = "Soy PlayerName. Me alegra haberte conocido así, ya que estoy seguro de que facilitarás mucho nuestra inves. aquí.",
  ui_story_5003_50030201_86_dialog_content = "Hmm, es un idea interesante. Debo solo pedirte para pagar.",
  ui_story_5003_50030201_87_dialog_content = "¿Las consultas están incluidas?",
  ui_story_5003_50030201_88_dialog_content = "Ya, ya, suficiente de eso. Hiiro y yo somos ambos de Sakae Dojo, lo sabes, ¿verdad?",
  ui_story_5003_50030201_89_dialog_content = "Lo se... Hiiro nos dijo algo sobre el dojo.",
  ui_story_5003_50030201_90_dialog_content = "Hmm, parece que ustedes son alguien en quien puedo confiar.",
  ui_story_5003_50030201_91_dialog_content = "<anim type=Shake><color=#e8d9bb>* Whoosh *—</color> </anim>",
  ui_story_5003_50030201_92_dialog_content = "Oye, ¿alguien acaba de salir corriendo?",
  ui_story_5003_50030201_93_dialog_content = "¿Eh? ¿Quién?",
  ui_story_5003_50030201_94_dialog_content = "No sé. No los reconocí.",
  ui_story_5003_50030201_95_dialog_content = "¡Daré un vistazo!",
  ui_story_5003_50030201_96_dialog_content = "<size=30>¿Eh? Te refieres a alguien simplemente...</size>",
  ui_story_5003_50030201_97_dialog_content = "(Vice y las demás parecen estar hab. de algo en los baños de mujeres.)",
  ui_story_5003_50030201_98_dialog_content = "<size=30>¡Shh! ¿Qué es el ruido afuera? Tweety, no salgas todavía. Vamos...</size>",
  ui_story_5003_50030201_99_dialog_content = "Vice, ¿están bien ahí dentro?",
  ui_story_5003_50030201_100_dialog_content = "¿PlayerName? Tú...",
  ui_story_5003_50030201_101_dialog_content = "Entré desde afuera para ver si había algo mal.",
  ui_story_5003_50030201_102_dialog_content = "¿Tratando de echar un vistazo? Nunca lo hubiera esperado...",
  ui_story_5003_50030201_103_dialog_content = "¿Eh? ¿Qué pasa?",
  ui_story_5003_50030201_104_dialog_content = "¿Eh-eh-eh? ¿Estabas tdatando de espiad?",
  ui_story_5003_50030201_105_dialog_content = "¿Espiar? No, ¡Eso no para nada! ¡No miré adentro!",
  ui_story_5003_50030201_106_dialog_content = "Acabo de ver a una persona sospechosa corriendo afuera, así que entré para ver qué pasaba.",
  ui_story_5003_50030201_107_dialog_content = "Es solo que este lugar no está tan insonorizado. Accidentalmente escuché...",
  ui_story_5003_50030201_108_dialog_content = "¿Qué escuchaste?",
  ui_story_5003_50030201_109_dialog_content = "Primero, escuché, \"No juegues con el yukata.\" ¡No, en serio no estaba escu. a escondidas!",
  ui_story_5003_50030201_110_dialog_content = "¡PlayerName! ¡Di la verdad!",
  ui_story_5003_50030201_111_dialog_content = "¡Espera! ¡Vice! ¡Realmente no miré!",
  ui_story_5003_50030201_112_dialog_content = "Entonces, ¿quién miraba desde afuera?",
  ui_story_5003_50030201_113_dialog_content = "Creo... ¿era un niño?",
  ui_story_5003_50030201_114_dialog_content = "¿¡Te refieres a un niño como tú!?",
  ui_story_5003_50030201_115_dialog_content = "¡No! ¡Creo que la persona que salió del hotel estaba espiando!",
  ui_story_5003_50030201_116_dialog_content = "Rec. haber visto a un chico sin camisa de pelo largo... ¡Quizá era de Calle Spa!",
  ui_story_5003_50030201_117_dialog_content = "Ni siq. tenemos chicas con pelo largo aquí...",
  ui_story_5003_50030201_118_dialog_content = "PlayerName, no me estás mintiendo, ¿verdad?",
  ui_story_5003_50030201_119_dialog_content = "¡Por supuesto que no!",
  ui_story_5003_50030201_X119_dialog_content = "Espera. Estoy seguro de que puedo reconocerlo si lo vuelvo a ver. ¡Vamos a enfrentarlo juntos!",
  ui_story_5003_50030301_1_dialog_content = "Maestro, ¿por qué la gente se volvió contra el dojo?",
  ui_story_5003_50030301_2_dialog_content = "Cuando nos enfren. a una crisis, todos hacemos lo que podemos para sobrevivir.",
  ui_story_5003_50030301_3_dialog_content = "Si la voluntad de sobrevivir se concentra en una cosa en par., puede conducir a un conflicto.",
  ui_story_5003_50030301_4_dialog_content = "Huimos para alejarnos de esos pelig. conflictos.",
  ui_story_5003_50030301_5_dialog_content = "Pero siempre me enseñaste a no tener nunca miedo a la muerte y a luchar con valen. hasta el final... Pero, Maestro... ¿nos escapamos?",
  ui_story_5003_50030301_6_dialog_content = "Huir no es siempre un acto de cobardía ni un abandono de la responsabilidad. La razón por la que hice lo que hice...",
  ui_story_5003_50030301_7_dialog_content = "Es porque tenía algo más importante que proteger. Tenía que man. la <color=#FFB400>llave</color> segura, Hiiro.",
  ui_story_5003_50030301_8_dialog_content = "¿Cuándo volveremos? ¿Cuándo terminen los conflictos?",
  ui_story_5003_50030301_9_dialog_content = "Hiiro, no vamos a volver...",
  ui_story_5003_50030301_10_dialog_content = "Comandante Hiiro, ¿te encuentras bien? ¿Tienes prob. para dormir bien de nuevo?",
  ui_story_5003_50030301_11_dialog_content = "No, estoy bien. Estaba pensando en algo.",
  ui_story_5003_50030301_12_dialog_content = "¡Están todos desp. tan temp.! Lo siento, no he tenido tiempo de prep. el desayuno.",
  ui_story_5003_50030301_13_dialog_content = "Lo siento, señora. Planeamos partir antes y no habíamos planeado molestarla.",
  ui_story_5003_50030301_14_dialog_content = "Por favor, no digas eso. Todo esto es parte del servicio aquí.",
  ui_story_5003_50030301_15_dialog_content = "No se preo. por nosotros. Hay algo que debemos investigar en las calles.",
  ui_story_5003_50030301_16_dialog_content = "Entonces... ¿Quieren desayunar a su regreso? Tweety y yo vamos al mercado a comprar buenos ingredientes.",
  ui_story_5003_50030301_17_dialog_content = "Son demasiado buenos. Pero comeremos afuera.",
  ui_story_5003_50030301_18_dialog_content = "Está bien, está bien.",
  ui_story_5003_50030301_19_dialog_content = "PlayerName, comencemos nuestra investigación con el hotel.",
  ui_story_5003_50030301_20_dialog_content = "De hecho, ayer aprovechamos nuestro tiempo en las aguas termales para preguntarle a Tweety sobre el hotel.",
  ui_story_5003_50030301_21_dialog_content = "No supimos nada sospechoso. Aunque la abuela dirige el hotel, no es la dueña.",
  ui_story_5003_50030301_22_dialog_content = "En términos generales, no hay nada extraño en comprar un terreno para construir un nuevo negocio.",
  ui_story_5003_50030301_23_dialog_content = "Sin embargo, hay algo especial en la tierra donde se construyó el dojo.",
  ui_story_5003_50030301_24_dialog_content = "En el Lejano Oriente, llamamos a un lugar como este \"suelo impío\".",
  ui_story_5003_50030301_25_dialog_content = "Verás, la gente tiende a man. alejada de los lugares donde se han prod. incidentes espantosos.",
  ui_story_5003_50030301_26_dialog_content = "¿Mantenerse alejado de ellos? El hotel parece que no tiene otros huéspedes.",
  ui_story_5003_50030301_27_dialog_content = "La fam. Sakae estuvo a punto de desa. de la noche a la mañana. Un fuego quemó el dojo, dejando solo ruinas en su lugar.",
  ui_story_5003_50030301_28_dialog_content = "¿Quién estaría disp. a comprar un terreno ensangrentado y construir un hotel de aguas termales sin clientes?",
  ui_story_5003_50030301_29_dialog_content = "Nec. encontrar al inversor. La abuela nos dijo que lo podemos encontrar en Calle Spa.",
  ui_story_5003_50030301_30_dialog_content = "Se llama...",
  ui_story_5003_50030301_31_option_content = "¡Taki! ¡Lo conozco!",
  ui_story_5003_50030301_32_dialog_content = "PlayerName, ¿cómo supiste el nombre del inversor?",
  ui_story_5003_50030301_33_dialog_content = "¡Ayer me dijo que era un inversor! ¡Hiiro, él es quien \"entrenó\" contigo! ¡Tu viejo comp. de dojo!",
  ui_story_5003_50030301_34_dialog_content = "¿Ese tipo?",
  ui_story_5003_50030301_35_dialog_content = "¿Dónde estabas ayer? ¿Cómo te encon. con él?",
  ui_story_5003_50030301_36_dialog_content = "Lo conocí en el hotel. Dije hola y terminamos charlando.",
  ui_story_5003_50030301_37_dialog_content = "¿No le preguntaste por el hotel?",
  ui_story_5003_50030301_38_dialog_content = "Realmente no... Nuestra conversación se interrumpió cuando vi a alguien corriendo fuera del hotel.",
  ui_story_5003_50030301_39_dialog_content = "Lo siento, realmente pensé que nos estabas espiando cuando estabas parado afuera de los baños de mujeres ayer.",
  ui_story_5003_50030301_40_dialog_content = "Bueno, ¡por sup. que no estaba! Solo estaba preo. de que si algo hubiera sucedido, te hubieran tatra. con la guardia baja...",
  ui_story_5003_50030301_41_dialog_content = "Así que decidí entrar primero y ver qué estaba pasando.",
  ui_story_5003_50030301_42_dialog_content = "¿Eh? ¿Es vedad que epiasste ayed?",
  ui_story_5003_50030301_43_dialog_content = "No, solo estaba escuchando... ¡Quiero decir, no! ¡No vi nada!",
  ui_story_5003_50030301_44_dialog_content = "Tweety, ¿qué haces aquí?",
  ui_story_5003_50030301_45_dialog_content = "¡Es mi tudno de haced la compa!",
  ui_story_5003_50030301_46_dialog_content = "Así que Piolín también está a cargo de las compras de comestibles.",
  ui_story_5003_50030301_47_dialog_content = "Tweety, ¿conoces a Taki?",
  ui_story_5003_50030301_48_dialog_content = "¡Conozdco a Taki! ¡Puedo buscadlo si me necesitas!",
  ui_story_5003_50030301_49_dialog_content = "Muy bien, contamos contigo para ayudarnos a encontrarlo.",
  ui_story_5003_50030301_50_dialog_content = "Así que hemos estado todo el día en la calle y no hemos vuelto a enc. nada, como ayer...",
  ui_story_5003_50030301_51_dialog_content = "Que dado... No puedo enc. al señor Taki hoy... ¿Desap. el señor en una soplo de humo?",
  ui_story_5003_50030301_52_dialog_content = "Taki edstuvo en Calle Spa los últimos días... ¿Quizá se fue a otro lugar hoy?",
  ui_story_5003_50030301_53_dialog_content = "¿Estaba <color=#FFB400>merodeando por Calle Spa</color>? ¿Qué estaba haciendo?",
  ui_story_5003_50030301_54_dialog_content = "El señor Taki dice que ha pasado un tiempo desde que regresó, así que quería hacer travesuras y volvería tarde.",
  ui_story_5003_50030301_55_dialog_content = "Mida la hoda... ¿Qué tal si todos degesan y descansan pimedo?",
  ui_story_5003_50030301_56_dialog_content = "Daré un chirrido cuando regrese el señor Taki.",
  ui_story_5003_50030301_57_dialog_content = "Si escucha que queremos verlo... Es probable que sospeche algo y evite encontrarse con nosotros.",
  ui_story_5003_50030301_58_option_content = "Creo que tienes razón.",
  ui_story_5003_50030301_59_dialog_content = "Cuando nos cono. ayer, se sorprendió un poco y preguntó: \"¿No acabas de llegar a los manantiales?\"",
  ui_story_5003_50030301_60_option_content = "No lo creo.",
  ui_story_5003_50030301_61_dialog_content = "Cuando vi a Taki ayer, se veía muy tranquilo cuando hablaba del dojo.",
  ui_story_5003_50030301_62_dialog_content = "No creo que tenga nada que ocultar.",
  ui_story_5003_50030301_63_dialog_content = "Bueno, ¿tal vez el Sr. Taki ya ha regresado al hotel?",
  ui_story_5003_50030301_64_dialog_content = "¿Quizás no lo vimos en la calle porque simplemente lo perdimos...?",
  ui_story_5003_50030301_65_dialog_content = "¡Ciedto, Ciedto!",
  ui_story_5003_50030301_66_dialog_content = "Entonces, cuando Taki regrese al hotel, primero nos informarás, ¿verdad, Tweety?",
  ui_story_5003_50030301_67_dialog_content = "¡Por supuesto! ¡Puedes confiad en mi!",
  ui_story_5003_50030301_68_dialog_content = "Muy bien, regresemos al hotel, entonces.",
  ui_story_5003_50030301_69_dialog_content = "PlayerName, ¿puedo pedirte que estés atento a cual. cosa extraña?",
  ui_story_5003_50030301_70_dialog_content = "¿Algo extraño?",
  ui_story_5003_50030301_71_dialog_content = "Así es. Creo que tu habilidad psíquica puede ser útil aquí.",
  ui_story_5003_50030301_72_dialog_content = "Bueno. Entiendo.",
  ui_story_5003_50030301_73_dialog_content = "Gha... Graaaah...",
  ui_story_5003_50030301_74_dialog_content = "Erm... Creo que acabo de escuchar algo extraño viniendo de...",
  ui_story_5003_50030301_75_dialog_content = "*Rugido*",
  ui_story_5003_50030301_76_dialog_content = "¡Ahhh! ¡Eclidsites!",
  ui_story_5003_50030301_77_dialog_content = "*Rugiendo*",
  ui_story_5003_50030301_78_dialog_content = "¿Cómo? ¿Qué edtán haciendo estos Eclidsites en la Calle Spa?",
  ui_story_5003_50030301_79_dialog_content = "¡Oh, no! ¡Hay demasiados de ellos!",
  ui_story_5003_50030301_80_dialog_content = "¡Estos Eclidsites no son tan dudos! ¡Puedo ayudad!",
  ui_story_5003_50030301_81_dialog_content = "¡Retrocede! ¡Dirígete al hotel! ¡El camino es estrecho aquí! ¡Bloquéalo!",
  ui_story_5003_50030301_82_dialog_content = "PlayerName, informa a abuela. ¡Nos ocuparemos de los Eclipsites de afuera!",
  ui_story_5003_50030301_83_dialog_content = "¡Bien!",
  ui_story_5003_50030301_84_dialog_content = "*Rugido*",
  ui_story_5003_50030301_85_dialog_content = "¡Oh, no! ¡Comandante Hiiro! ¡Eclipsites se dirigen calle abajo!",
  ui_story_5003_50030301_86_dialog_content = "¡Los detendré!",
  ui_story_5003_50030301_87_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030301_88_dialog_content = "¿Quién se esconde ahí? ¡Muéstrate!",
  ui_story_5003_50030301_89_dialog_content = "Nos vol. a encontrar, Hiiro.",
  ui_story_5003_50030301_90_dialog_content = "¡Señora! Señora, ¿dónde está? ¿¡Señora!?",
  ui_story_5003_50030301_91_dialog_content = "Extraño... ¿No hay nadie en el hotel?",
  ui_story_5003_50030301_92_dialog_content = "Espera...",
  ui_story_5003_50030301_X92_dialog_content = "¿Quién se esconde en el patio? ¡Muéstrate!",
  ui_story_5003_50030301_93_dialog_content = "Estás...",
  ui_story_5003_50030301_94_dialog_content = "...",
  ui_story_5003_50030301_95_dialog_content = "Eres el tipo que salió corriendo anoche, ¿no?",
  ui_story_5003_50030301_96_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030301_97_dialog_content = "Los Eclipsites casi han sido derrotados. ¿De qué querías hablarme? Adelante, dilo.",
  ui_story_5003_50030301_98_dialog_content = "Taki, ¿por qué construirías un hotel en los terrenos del Sakae Dojo?",
  ui_story_5003_50030301_99_dialog_content = "La única razón que se me ocurre es que querías ocultar algo.",
  ui_story_5003_50030301_100_dialog_content = "El Sakae Dojo ya no existe. El terreno estaba disp., así que, nat., lo compré.",
  ui_story_5003_50030301_101_dialog_content = "¿¡Qué dijiste!?",
  ui_story_5003_50030301_102_dialog_content = "Cálmate. Si vas a dejar que tus emo. te dominen, te aconsejo que olvides esta línea de preguntas.",
  ui_story_5003_50030301_103_dialog_content = "La familia Sakae fue asesinada por sus <color=#FFB400>enemigos</color>. El Maestro no tuvo más remedio que huir conmigo, ¿y quieres que me calme?",
  ui_story_5003_50030301_104_dialog_content = "<size=45>¡Estoy aquí para vengarme!</size>",
  ui_story_5003_50030301_105_dialog_content = "Ni siq. puedes distinguir entre amigos y enem. en este momento. Ya te lo dije, soy tu compañero discípulo.",
  ui_story_5003_50030301_106_dialog_content = "¿Ves esta cicatriz en mi cara? Esto lo dejó tu maestro, el jefe del Sakae Dojo, <color=#FFB400>Sakae Shigeo</color>.",
  ui_story_5003_50030301_107_dialog_content = "¿Mi maestro? ¿Pero por qué?",
  ui_story_5003_50030301_108_dialog_content = "Sakae Shigeo pensó que era demasiado flacucho y débil. La mirada en sus ojos me dijo que no me aceptaría como discípulo.",
  ui_story_5003_50030301_109_dialog_content = "Entonces lo ataqué ... y me cortó, pero también admitió que tenía potencial.",
  ui_story_5003_50030301_110_dialog_content = "¿Entonces te aceptó como discípulo del Sakae Dojo?",
  ui_story_5003_50030301_111_dialog_content = "Correcto. Le juré a Sakae Shigeo que si no podía vencerlo en tres años, me iría por mi propia voluntad.",
  ui_story_5003_50030301_112_dialog_content = "Y que no le diría a nadie que era un discípulo del clan Sakae para no avergonzar a Sakae.",
  ui_story_5003_50030301_113_dialog_content = "¿Ganaste al final?",
  ui_story_5003_50030301_114_dialog_content = "No, me dejó ganar... Al final, dejé Montaña Nube y me fui al continente.",
  ui_story_5003_50030301_115_dialog_content = "No le he dicho a nadie que soy un discípulo del clan Sakae, así que no me gusta que me sospechen sin razón.",
  ui_story_5003_50030301_116_dialog_content = "Tú eres quien me atacó primero. Solo sospeché de ti porque no sabía la verdad.",
  ui_story_5003_50030301_117_dialog_content = "Solo estábamos combate. No estaba tratando de lastimarte. Incluso si no me conocías, deberías conocer el estilo Sakae.",
  ui_story_5003_50030301_118_dialog_content = "No recibí la noticia hasta después de la caída del Sakae Dojo.",
  ui_story_5003_50030301_119_dialog_content = "Así que todo lo que pude hacer fue comprar la tierra donde estaba el dojo para que no cayera en manos de nadie más.",
  ui_story_5003_50030301_120_dialog_content = "Cuando nos conocimos, dijiste <color=# FFB400>\"Montaña Nube está a salvo ahora\".</color> ¿Qué quisiste decir con eso?",
  ui_story_5003_50030301_121_dialog_content = "Investigué un poco. Los asaltantes del dojo ya se fueron.",
  ui_story_5003_50030301_122_dialog_content = "¿Qué les pasó a ellos?",
  ui_story_5003_50030301_123_dialog_content = "Fueron asesinados. O quizá los discípulos de Sakae Dojo lucharon valientemente y perecieron durante la batalla.",
  ui_story_5003_50030301_124_dialog_content = "¿Perecieron juntos en batalla? Así que, quieres decir... ¿Mis enem. ya fueron derrotados antes de que regresara?",
  ui_story_5003_50030301_125_dialog_content = "Correcto. Se acabó.",
  ui_story_5003_50030301_126_dialog_content = "Somos del mismo dojo, después de todo. Te digo esto porque no quiero verte esclavizada por el pasado.",
  ui_story_5003_50030301_127_dialog_content = "...",
  ui_story_5003_50030301_128_dialog_content = "La abuela me acercó y me dijo que quería construir un hotel.",
  ui_story_5003_50030301_129_dialog_content = "Te refieres a... ¿No eres tú quien quería construir un hotel en este terreno? ¿Fue ella?",
  ui_story_5003_50030301_130_dialog_content = "¿Qué estaba tratando de ocultar construyendo un hotel sobre las ruinas del dojo?",
  ui_story_5003_50030401_1_dialog_content = "Niño tonto... ¿Qué estás haciendo colapsado en mi puerta así? No has comido bien en mucho tiempo, ¿eh?",
  ui_story_5003_50030401_2_dialog_content = "¿Eres ... el que estaba haciendo guardia hace dos días?",
  ui_story_5003_50030401_3_dialog_content = "Así es... ¿Crees que soy muy mayor para dar pelea?",
  ui_story_5003_50030401_4_dialog_content = "Usted debe estar bromeando...",
  ui_story_5003_50030401_X4_dialog_content = "<size=45>¡Te dejo fuera fácil! ¿¡De verdad crees que eres mejor que yo!?</size>",
  ui_story_5003_50030401_5_dialog_content = "Jeje, cálmate y entra. La cena está lista.",
  ui_story_5003_50030401_6_dialog_content = "¿Me estás dejando entrar?",
  ui_story_5003_50030401_7_dialog_content = "Cómo podría no dejarte entrar.",
  ui_story_5003_50030401_X7_dialog_content = "Este es un hotel...",
  ui_story_5003_50030401_8_dialog_content = "¿Dónde estoy? ¿Quién es usted?",
  ui_story_5003_50030401_9_dialog_content = "Este es un dojo. Soy Sanki.",
  ui_story_5003_50030401_10_dialog_content = "¿Por qué me ataste? ¿Qué me vas a hacer?",
  ui_story_5003_50030401_11_dialog_content = "Tuve que evitar que te agitaras.",
  ui_story_5003_50030401_12_dialog_content = "Entonces, ¿qué me vas a hacer?",
  ui_story_5003_50030401_13_dialog_content = "Tranquilízate. ¿Crees que soy tonto? Yo soy el que hace las preg. aquí.",
  ui_story_5003_50030401_14_dialog_content = "Bien, si tu lo dices... Pero, ¿qué quisiste decir al decir que esto es un dojo?",
  ui_story_5003_50030401_15_dialog_content = "Pensé que el dojo fue destruido hace mucho tiempo. Este no puede ser el lugar.",
  ui_story_5003_50030401_16_dialog_content = "Este no puede ser el dojo, ¿eh?",
  ui_story_5003_50030401_X16_dialog_content = "¡Jajajaja!",
  ui_story_5003_50030401_17_dialog_content = "Nunca has visto el dojo. Parece que realmente no sabes nada.",
  ui_story_5003_50030401_S18_dialog_content = "El dojo fue destruido, pero parte de él aún se enc. escondido debajo del Hotel Flor de Nube.",
  ui_story_5003_50030401_S19_dialog_content = "Lo siento, realmente no sé nada... ¿Por qué no me cuentas más?",
  ui_story_5003_50030401_S20_dialog_content = "¡Cállate! ¡Ya he dicho suficiente! ¿¡Crees que soy una especie de tonto!?",
  ui_story_5003_50030401_S21_dialog_content = "¡Lo siento! Está bien si no quieres hablar sobre el dojo. Cambiemos de tema.",
  ui_story_5003_50030401_X18_dialog_content = "Tu espada es tan genial. ¿Todos en el Lejano Oriente tienen una espada?",
  ui_story_5003_50030401_19_dialog_content = "¡Dije que te callaras! ¡Ni siquiera te buscaba a ti! ¡Así que deja de intentar hablarme!",
  ui_story_5003_50030401_20_dialog_content = "¡...!",
  ui_story_5003_50030401_21_dialog_content = "(Este tipo real. golpeó a alguien... Si supiera... Habría dejado de hablar.)",
  ui_story_5003_50030401_22_dialog_content = "¿PlayerName? ¿PlayerName? ¿Dónde estás?",
  ui_story_5003_50030401_23_dialog_content = "¿PlayerName? ¿Abuedita? ¿Dónde estás?",
  ui_story_5003_50030401_24_dialog_content = "Vice, ¿qué está pasando?",
  ui_story_5003_50030401_25_dialog_content = "PlayerName y la abuela no están en el hotel... Pero PlayerName dirigía en esta dirección hace un momento...",
  ui_story_5003_50030401_26_dialog_content = "Echemos otro vistazo...",
  ui_story_5003_50030401_27_dialog_content = "¡Vice! ¡Hiiro! ¡Poblemad!",
  ui_story_5003_50030401_28_dialog_content = "¿Qué pasa?",
  ui_story_5003_50030401_29_dialog_content = "No pude encontad a Abuedita, ¡pero encontdé una nota!",
  ui_story_5003_50030401_30_dialog_content = "Descendiente de la familia Sakura: ¡Deja Montaña Nube inmediatamente!",
  ui_story_5003_50030401_X30_dialog_content = "De lo contrario, ¡les pasará algo terrible a ti y tus compañeros de viaje!",
  ui_story_5003_50030401_31_dialog_content = "Además, si alguna vez quieres volver a ver a PlayerName vivo, ve a Calle Spa y espera.",
  ui_story_5003_50030401_32_dialog_content = "¿¡Alguien tomó como rehén a PlayerName!?",
  ui_story_5003_50030401_33_dialog_content = "<color=#e8d9bb>*agita, agita... quiebra, quiebra...*</color>",
  ui_story_5003_50030401_34_dialog_content = "(Suena como si algo estuviera... <color=#FFB400>¿temblando</color>?)",
  ui_story_5003_50030401_35_dialog_content = "... ¿¡Quién anda ahí!?",
  ui_story_5003_50030401_36_dialog_content = "(¿Ese sonido viene del exterior...? Sanki... ¡El salió!)",
  ui_story_5003_50030401_37_dialog_content = "(¡Ahora es mi opor. de enc. una salida a este lío!)",
  ui_story_5003_50030401_38_dialog_content = "(Apenas puedo moverme... Espera un minuto, ¡puedo llamar a alguien con mis hab. psíquicas!)",
  ui_story_5003_50030401_39_dialog_content = "<color=#e8d9bb>*clic... clic... shoom...*</color>",
  ui_story_5003_50030401_40_dialog_content = "(De ninguna manera... ¿Ya ha vuelto?)",
  ui_story_5003_50030401_41_dialog_content = "Espera... ¡Esa es...!",
  ui_story_5003_50030401_42_dialog_content = "¿¡Abuelita!?",
  ui_story_5003_50030401_43_dialog_content = "Shh, silencio ahora, niña.",
  ui_story_5003_50030401_44_dialog_content = "¿Qué estás haciendo aquí?",
  ui_story_5003_50030401_45_dialog_content = "Podemos hablar de eso luego. Déjame desatar estas cuerdas primero... Vamos a salir de aquí.",
  ui_story_5003_50030401_46_dialog_content = "¿Qué está pasando aquí?",
  ui_story_5003_50030401_47_dialog_content = "Hija mía, espero que no culpes a Sanki por lo que hizo. <color=#FFB400>Solo quiere proteger Montaña Nube</color>.",
  ui_story_5003_50030401_48_dialog_content = "¿Protegerla de qué?",
  ui_story_5003_50030401_49_dialog_content = "Lo siento, pero no puedo contarte todos los sec. de Montaña Nube. Sin embargo, puedo explicar parte del motivo.",
  ui_story_5003_50030401_50_dialog_content = "Montaña Nube está prot. por la barrera exterior, pero su llegada aquí la ha afec. de alguna manera, provo. la invasión de los Eclipsites.",
  ui_story_5003_50030401_51_dialog_content = "Sanki estaba tratando de obli. a irte porque trajeron peligro a Montaña Nube...",
  ui_story_5003_50030401_52_dialog_content = "Ya lo he regañado. Espero que puedan perd. por lo que hizo.",
  ui_story_5003_50030401_53_dialog_content = "Pero no entiendo ... ¿Por qué nuestra presencia aquí afectaría la barrera?",
  ui_story_5003_50030401_54_dialog_content = "Salgamos primero. Te lo explicaré cuando nos encontremos con Hiiro, ¿de acuerdo?",
  ui_story_5003_50030401_55_dialog_content = "Ok.",
  ui_story_5003_50030401_56_dialog_content = "¿PlayerName? ¿Dónde estabas? ¡Te hemos estado bus. por mucho tiempo!",
  ui_story_5003_50030401_57_dialog_content = "Tú... ¿no fuiste a Calle Spa a esperar?",
  ui_story_5003_50030401_58_dialog_content = "¿Calle Spa?",
  ui_story_5003_50030401_59_dialog_content = "Parece que la abuela escribió la nota pidiéndonos que nos fuéramos...",
  ui_story_5003_50030401_60_dialog_content = "Lo siento. Pero pensé que sería mejor que dejaran Montaña Nube.",
  ui_story_5003_50030401_61_dialog_content = "¿Puedes explicar qué está pasando aquí, abuela?",
  ui_story_5003_50030401_62_dialog_content = "¿Por qué construiste un hotel sobre las ruinas del dojo?",
  ui_story_5003_50030401_63_dialog_content = "Bueno, construí el hotel para proteger el dojo.",
  ui_story_5003_50030401_65_dialog_content = "Supongo que no hay forma de que pueda ocul., pero esto es solo entre Hiiro y en quienes ella confía.",
  ui_story_5003_50030401_66_dialog_content = "Ven conmigo, Tweety.",
  ui_story_5003_50030401_67_dialog_content = "Dien. ¡No te preo., Abuedita! ¡Yo velaré por el stweet! ¡No mojaré a nadie!",
  ui_story_5003_50030401_68_dialog_content = "Buen chico. Gracias.",
  ui_story_5003_50030401_69_dialog_content = "No deberías haber vuelto, Hiiro.",
  ui_story_5003_50030401_70_dialog_content = "Sakae Shigeo no te habría permitido volver.",
  ui_story_5003_50030401_71_dialog_content = "Abuelita... ¿Quién eres tú?",
  ui_story_5003_50030401_72_dialog_content = "Cuando era joven, solía ser el ama de llaves de la fam. Sakura y también un mensajero que entrega info. secreta.",
  ui_story_5003_50030401_73_dialog_content = "La Familia Sakura y la Familia Sakae eran las dos fuerzas prin. que custo. la barrera de la Montaña Nube.",
  ui_story_5003_50030401_74_dialog_content = "Las dos fam. invitaron al carpintero más hábil de todo Underwell a construir una habitación secreta en el dojo.",
  ui_story_5003_50030401_75_dialog_content = "Sellaron algo muy importante allí... Algo que encierra un gran poder y mantiene la barrera.",
  ui_story_5003_50030401_76_dialog_content = "Solo cuando ambas fam. estén aquí se podrá usar su sangre para levantar el sello.",
  ui_story_5003_50030401_77_dialog_content = "Pero una vez que se levanta el sello, la estab. de la barrera será destruida por el gran poder de este \"objeto importante\".",
  ui_story_5003_50030401_78_dialog_content = "Y Eclipsites inundarán como una avalancha.",
  ui_story_5003_50030401_79_dialog_content = "Desesperados por adquirir este \"objeto\", <color=#FFB400>El resen. de las fuerzas del mal del Lejano Oriente contra la Fam. Sakae</color> creció...",
  ui_story_5003_50030401_80_dialog_content = "En esa fatídica noche, el Sakae Dojo fue atacado.",
  ui_story_5003_50030401_81_dialog_content = "<color=#FFB400> La hab. secreta se encuentra bajo tierra</color>, y el sello estaba inmerso con sangre de la fam. Sakae.",
  ui_story_5003_50030401_82_dialog_content = "Hiiro, que resta de nuestra línea de sangre, afectará el sello.",
  ui_story_5003_50030401_83_dialog_content = "Solo regresé a Montaña Nube para inves. cosas sobre la Familia Sakae.",
  ui_story_5003_50030401_84_dialog_content = "<size=45>Tu existencia rep. el mayor secreto de la familia Sakae y Sakura </size>.",
  ui_story_5003_50030401_85_dialog_content = "Te reconocí tan pronto como te vi. Me recuerdas a tu madre y a tu abuela.",
  ui_story_5003_50030401_86_dialog_content = "Crecí con tu abuela... pero todos murieron hace mucho tiempo.",
  ui_story_5003_50030401_87_dialog_content = "Esta es una carta de tu madre. Es una prueba de que lo que he dicho es cierto.",
  ui_story_5003_50030401_88_dialog_content = "Ahora ve... Manténgase lejos de aquí antes que los Eclipsites monten otro ataque.",
  ui_story_5003_50030401_89_dialog_content = "Entonces, mientras me vaya, ¿Montaña Nube estará a salvo?",
  ui_story_5003_50030401_90_dialog_content = "Sí.",
  ui_story_5003_50030401_91_option_content = "¿Por qué no te vas con nosotros?",
  ui_story_5003_50030401_92_dialog_content = "Por favor, perdóname, pero no puedo ir contigo.",
  ui_story_5003_50030401_93_dialog_content = "Debo quedarme aquí para vigilar el hotel y la hab. secreta que hay debajo.",
  ui_story_5003_50030401_94_option_content = "Hiiro, ¿qué vas a hacer?",
  ui_story_5003_50030401_95_dialog_content = "Ya veo. Saber que estás aquí ha hecho que todo este viaje valga la pena.",
  ui_story_5003_50030401_96_dialog_content = "Dejaré Montaña Nube, pero me temo que los Eclipsites volverán a invadir...",
  ui_story_5003_50030401_97_dialog_content = "Así que, me gustaría pedir a Vice y PlayerName que se queden aquí por el mom. para gar. la seguridad de todos.",
  ui_story_5003_50030401_98_dialog_content = "Espera... Sin el Colossus... ¿Cómo piensas irte de aquí sola, Hiiro?",
  ui_story_5003_50030401_99_dialog_content = "No te preocupes. Iré al puerto yo sola.",
  ui_story_5003_50030401_100_dialog_content = "Hiiro, la gente de aquí está muy preocupada por tu presencia...",
  ui_story_5003_50030401_101_dialog_content = "Dicen que trajiste a los Eclipsites y la calamidad a Montaña Nube.",
  ui_story_5003_50030401_102_dialog_content = "Sanki incluso atacó a PlayerName.",
  ui_story_5003_50030401_X102_dialog_content = "Por eso creo que deberían irse todos juntos...",
  ui_story_5003_50030401_103_dialog_content = "Nunca pensé que nuestro viaje a Montaña Nube term. de esta manera...",
  ui_story_5003_50030401_104_dialog_content = "Shh, no lo menciones PlayerName, o molestarás a Comandante Hiiro.",
  ui_story_5003_50030401_105_dialog_content = "No tienes que preocuparte por mí. Estoy bien con el final de este viaje.",
  ui_story_5003_50030401_106_dialog_content = "Llegamos a conocer al Sr. Taki y Tweety. Eso debería facilitarnos mucho las cosas si necesitamos investigar Montaña Nube en el futuro.",
  ui_story_5003_50030401_107_dialog_content = "Y leí esa carta. Creo que lo que dijo la abuela es cierto.",
  ui_story_5003_50030401_108_dialog_content = "Me enteré de su historia y de la historia de mi familia. El viaje valió la pena.",
  ui_story_5003_50030401_109_dialog_content = "Eso es genial. Comandante Hiiro, finalmente puede dejar Montaña Nube con una sonrisa.",
  ui_story_5003_50030401_110_dialog_content = "¿Por qué dices eso?",
  ui_story_5003_50030401_111_dialog_content = "Siento que has estado estresada todo este tiempo. He estado un poco preocupado por ti...",
  ui_story_5003_50030401_112_dialog_content = "Gracias por tu preocupación.",
  ui_story_5003_50030401_113_dialog_content = "Al principio, tenía algunas... sospechas, pero sé que todo estará bien.",
  ui_story_5003_50030401_114_dialog_content = "Mi maestro dijo que no quería que volviera a Montaña Nube, pero no me dijo por qué.",
  ui_story_5003_50030401_115_dialog_content = "Pensando en eso ahora, tal vez solo quería protegerme.",
  ui_story_5003_50030401_116_dialog_content = "Sin embargo, cuando mi maestro murió, su último deseo fue que \"encontrara mi futuro en la espada del Sakae\".",
  ui_story_5003_50030401_117_dialog_content = "No entendí lo que esto significaba, pero después de que mi espada Sakae comenzó a cambiar, me decidí a regresar a Montaña Nube.",
  ui_story_5003_50030401_118_dialog_content = "Aunque todavía no entiendo por qué, mientras continúe persiguiendo los secretos de la espada Sakae, algún día lo entenderé.",
  ui_story_5003_50030401_119_dialog_content = "Es solo que parece que todavía no podré calmar sus <color=#FFB400>vibraciones</color>aún...",
  ui_story_5003_50030401_120_dialog_content = "Espera... ¿Qué quieres decir con \"calmar sus vibraciones\"?",
  ui_story_5003_50030401_121_dialog_content = "Puedo sentirla temblar. Quizá suene ridículo.",
  ui_story_5003_50030401_122_dialog_content = "Pero eso es justo lo que pasó. Primero fue hace siete días, luego hace unas horas volvió a temblar. Esta es la tercera vez ahora.",
  ui_story_5003_50030401_123_dialog_content = "<color=#e8d9bb>*Brrr*</color>",
  ui_story_5003_50030401_124_dialog_content = "Ese zumbido... ¿Es esa la espada vibrando?",
  ui_story_5003_50030401_125_dialog_content = "Hiiro, este sonido... Creo que lo escuché antes en el dojo.",
  ui_story_5003_50030401_126_dialog_content = "¡El arma de Sanki estaba temblando como tu Espada Sakae!",
  ui_story_5003_50030401_127_dialog_content = "Pero eso no puede ser... A menos que su espada...",
  ui_story_5003_50030401_128_dialog_content = "¿¡También es una <color=#FFB400>Espada Sakae</color>!?",
  ui_story_5003_50030401_129_dialog_content = "Solo las llamas abrasadoras y la sangre de los Sakae pueden trans. una katana en una Espada Sakae.",
  ui_story_5003_50030401_130_dialog_content = "Las fuerzas del mal que ata. a la familia Sakae, mis enemigos...",
  ui_story_5003_50030401_131_dialog_content = "<size=45>¡Sus espadas estaban cubiertas con la sangre de los Sakae y prendieron fuego a nuestra casa!</size>",
  ui_story_5003_50030401_X131_dialog_content = "¿¡Quieres decir que Sanki es uno de esos enemigos!?",
  ui_story_5003_50030501_1_dialog_content = "PlayerName, es la única posibilidad que se me ocurre. ¡Tiene una espada Sakae!",
  ui_story_5003_50030501_2_dialog_content = "El Maestro me dijo antes de morir que esta espada estaba bañada en la sangre del Sakae.",
  ui_story_5003_50030501_3_dialog_content = "Después de templarlo en llamas, la hoja renacerá y se convertirá en una Espada Sakae.",
  ui_story_5003_50030501_4_dialog_content = "Las fuerzas del mal del Lejano Oriente que masa. a la familia Sakae... A los que llamábamos enemigos...",
  ui_story_5003_50030501_5_dialog_content = "Sus espadas estaban cub. con la sangre de los Sakae, ¡y pren. fuego a nuestra casa!",
  ui_story_5003_50030501_6_dialog_content = "Pero abuela debe haber sabido sobre Sanki, ¿por qué no nos lo dijo?",
  ui_story_5003_50030501_7_dialog_content = "La abuela solo cuida de la familia, me ha dicho que no sabe mucho sobre Sakae.",
  ui_story_5003_50030501_8_dialog_content = "¿Quizá ella no conoce la verdadera identidad de Sanki?",
  ui_story_5003_50030501_9_dialog_content = "PlayerName, ¡debemos regresar a Montaña Nube de inmediato!",
  ui_story_5003_50030501_10_dialog_content = "¿Sabes cuánta sangre he derramado en este día?",
  ui_story_5003_50030501_11_dialog_content = "Mira estas hojas... <color=#FFB400>¡Cada vez que me acerco al sello, comienzan a temblar</color>! ¡Y rugen!",
  ui_story_5003_50030501_12_dialog_content = "Ahora solo nec. una última cosa—¡Hiiro de la Fam. Sakura!",
  ui_story_5003_50030501_13_dialog_content = "¡Entonces al fin podré cumplir con lo que he anhelado todos estos años!",
  ui_story_5003_50030501_14_dialog_content = "¿¡Cómo te atreves a dejarla ir!?",
  ui_story_5003_50030501_15_dialog_content = "Con calma, Sanki. Déjame explicar...",
  ui_story_5003_50030501_16_dialog_content = "¿Quieres que me calme? ¿¡Quieres que escuche más de tus mentiras!?",
  ui_story_5003_50030501_17_dialog_content = "¡Me alejaste delib. y dejaste ir a ese tipo, y luego dejaste que Hiiro se fuera! ¡Eso es lo que hiciste!",
  ui_story_5003_50030501_18_dialog_content = "¡Sabes quién era yo desde el primer día que nos conocimos! ¡Has estado plan. detenerme todo el tiempo, no es así!",
  ui_story_5003_50030501_19_dialog_content = "No estaba planeando matarte, ¿así que crees poder vencerme? ¿Es así?",
  ui_story_5003_50030501_20_dialog_content = "No, escúchame. No puedes destruir esa cosa protegida por el sello. Una vez que lo destruyas, Montaña Nube...",
  ui_story_5003_50030501_21_dialog_content = "¡Cállate! ¡No quiero escuchar otra palabra tuya!",
  ui_story_5003_50030501_X21_dialog_content = "Realmente no crees que te voy a matar, ¿verdad?",
  ui_story_5003_50030501_X23_dialog_content = "Dame tu sangre.",
  ui_story_5003_50030501_22_dialog_content = "Sanki, te lo dije antes, ¡no soy miembro de la Familia Sakura!",
  ui_story_5003_50030501_23_dialog_content = "¡Pero aún no he probado tu sangre!",
  ui_story_5003_50030501_X22_dialog_content = "Nunca olvido la ira de Underwell...",
  ui_story_5003_50030501_24_dialog_content = "¿No es natural que los derrotados renuncien a su vida? Si pierdes, debes pagar el precio con sangre.",
  ui_story_5003_50030501_25_dialog_content = "Y una vez que abra la puerta y destruya lo que hay dentro, mi venganza estará completa.",
  ui_story_5003_50030501_26_dialog_content = "¿No es así... Sakae?",
  ui_story_5003_50030501_27_dialog_content = "Casi olvido por qué vine, pero me recordaste.",
  ui_story_5003_50030501_28_dialog_content = "Debo agradecerte, Hiiro. Caminaste directo hacia mis manos.",
  ui_story_5003_50030501_29_dialog_content = "Jaja... Jajajajaja...",
  ui_story_5003_50030501_30_dialog_content = "Jah... ¿Qué me dijo mi padre la noche que se fue? Lo he olvidado ahora.",
  ui_story_5003_50030501_31_dialog_content = "¡Sanki! ¡Déjala en paz!",
  ui_story_5003_50030501_32_dialog_content = "¿¡Hiiro!?",
  ui_story_5003_50030501_33_dialog_content = "¡Jajaja! ¡Mira, abuela! ¡Tu Hiiro ha regresado! ¡Ella regresó sola!",
  ui_story_5003_50030501_34_dialog_content = "H... ¡Hiiro! No seas precipitado...",
  ui_story_5003_50030501_35_dialog_content = "Si tienes algún resen. contra mí, ven a mí. No es nec. que le hagas daño.",
  ui_story_5003_50030501_36_dialog_content = "Por supuesto... Mientras te quedes aquí, la dejaré ir.",
  ui_story_5003_50030501_37_dialog_content = "Muy bien, lo prometo. Vice, PlayerName, protejan a la abuela.",
  ui_story_5003_50030501_38_dialog_content = "¡Abuela, ven a mí!",
  ui_story_5003_50030501_39_dialog_content = "¡No te preocupes! ¡Sanki no me hará daño! ¡No es nuestro enemigo! ¡Es solo el hijo del carpintero!",
  ui_story_5003_50030501_40_dialog_content = "¡Cállate! ¡Basta de palabras!",
  ui_story_5003_50030501_41_dialog_content = "¡Hiiro! Después de que use tu sangre para romper el sello, te lo contaré todo.",
  ui_story_5003_50030501_42_dialog_content = "Solo nec. que me digas de dónde vino la espada que tienes en la mano... ¿¡Eres enemigo de mi familia!?",
  ui_story_5003_50030501_43_dialog_content = "¡Si es así, tendré mi venganza!",
  ui_story_5003_50030501_X43_dialog_content = "...",
  ui_story_5003_50030501_X44_dialog_content = "¡Qué broma!",
  ui_story_5003_50030501_X45_dialog_content = "¿¡Qué!?",
  ui_story_5003_50030501_44_dialog_content = "¿¡Todavía tienes valor parlot. sobre venganza!?",
  ui_story_5003_50030501_45_dialog_content = "La gente de Underwell quedó atrapada en la lucha entre Sakae y sus enem. sin ningún motivo, y fueron masacrados en solo una noche...",
  ui_story_5003_50030501_46_dialog_content = "Puse fin a esas fuerzas del mal. ¡Maté a todos esos enemigos! ¡Solo mira las Espadas Sakae en mis manos!",
  ui_story_5003_50030501_47_dialog_content = "¡Estas espadas que tomé de los enem. son prueba de mi venganza! ¡Lo que hice fue una ver. venganza!",
  ui_story_5003_50030501_48_dialog_content = "En cuanto a ti, tomaré tu vida y la usaré para destruir <size=45>la fuente de todo esto—¡la cosa detrás del sello</size>!",
  ui_story_5003_50030501_49_dialog_content = "¡No puedo dejar que destruyas el imp. objeto sellado aquí! ¡La seg. de Montaña Nube depende de ello!",
  ui_story_5003_50030501_50_dialog_content = "¡Basta de hablar! ¡Hiiro, no te mereces la Espada Sakae! ¡Sakae Shigeo, hoy reclamo mi octava espada!",
  ui_story_5003_50030501_51_dialog_content = "El destino de Montaña Nube y esta Espada Sakae... ¡Ninguna caerá en tus manos!",
  ui_story_5003_50030501_52_dialog_content = "¿Qué ocurre? ¿No eres un orgulloso discípulo de Sakae Shigeo?",
  ui_story_5003_50030501_53_dialog_content = "¡Jajaja! ¿¡Ni siquiera puedes defenderte!?",
  ui_story_5003_50030501_54_dialog_content = "¡Hiiro! ¡Enfócate!",
  ui_story_5003_50030501_55_dialog_content = "Enfoca tu mente y dale a la espada todo lo que tienes.",
  ui_story_5003_50030501_56_dialog_content = "Todo lo que tengo...",
  ui_story_5003_50030501_57_dialog_content = "Zakura, Sakae, poder transitorio...",
  ui_story_5003_50030501_58_dialog_content = "Y una det. temerosa de la muerte, esto es todo lo que tengo.",
  ui_story_5003_50030501_59_dialog_content = "¡¡¡!!!",
  ui_story_5003_50030501_60_dialog_content = "Has perdido, Sanki.",
  ui_story_5003_50030501_61_dialog_content = "Jaja... *tose*",
  ui_story_5003_50030501_62_dialog_content = "Perdí... Entonces, mátame...",
  ui_story_5003_50030501_63_dialog_content = "El ganador decide el destino de los derrotados. Cuando mato a mis enemigos, les digo lo mismo.",
  ui_story_5003_50030501_66_dialog_content = "¡Espera! ¡Hiiro! ¡No lo mates!",
  ui_story_5003_50030501_67_dialog_content = "Yo se. No es mi \"enemigo\"... Dime quién es, abuela.",
  ui_story_5003_50030501_68_dialog_content = "Es el hijo del carp. de Underwell que construyó la habitación secreta para la familia Sakae.",
  ui_story_5003_50030501_69_dialog_content = "Su familia... fue víctima de la masacre esa noche.",
  ui_story_5003_50030501_70_dialog_content = "*Tose* Mi padre... accedió a construir la cámara secreta...",
  ui_story_5003_50030501_71_dialog_content = "Para poder convertirme en discípulo del Sakae Dojo.",
  ui_story_5003_50030501_72_dialog_content = "¡Todo es por esa cosa detrás del sello! ¡La causa de toda esta muerte y destrucción!",
  ui_story_5003_50030501_74_dialog_content = "No, el objeto sellado aquí es demasiado importante para Cloud Mountain, así que todos sacrificaron todo para protegerlo...",
  ui_story_5003_50030501_75_dialog_content = "¡Basta de tonterías! ¡Hazlo!",
  ui_story_5003_50030501_76_dialog_content = "Está bien...",
  ui_story_5003_50030501_77_dialog_content = "...",
  ui_story_5003_50030501_S77_dialog_content = "¿Solo me cortaste el pelo?",
  ui_story_5003_50030501_X77_dialog_content = "¿¡Por qué estás haciendo esto!? ¿Por qué no me acabas?",
  ui_story_5003_50030501_X78_dialog_content = "Ya te acabé...",
  ui_story_5003_50030501_78_dialog_content = "\"Tú\" estás muerto— el \"tú\" que estaba obses. con la venganza ha sido derrotado.",
  ui_story_5003_50030501_79_dialog_content = "Espero que puedas olvidarlo y ponerle fin... Renuncia a esta idea de destruir el sello.",
  ui_story_5003_50030501_80_dialog_content = "¡Preferiría que me mataras antes que conver. en un desertor cobarde como tú y Sakae Shigeo!",
  ui_story_5003_50030501_81_dialog_content = "Hubo un momento en que no entendía cómo podía huir en tal situación.",
  ui_story_5003_50030501_82_dialog_content = "Pero Sakae Shigeo... Mi maestro ... nunca tuvo miedo de mirar a la muerte a la cara.",
  ui_story_5003_50030501_X82_dialog_content = "Estaba tratando de llevarme a mí, la \"llave\" del sello, lejos de aquí.",
  ui_story_5003_50030501_83_dialog_content = "Maestro, ¡¿se volvió a abrir tu vieja herida?!",
  ui_story_5003_50030501_84_dialog_content = "Los Eclipsites estarán aquí pronto, y nadie puede defender el camino hacia el refugio excepto nosotros.",
  ui_story_5003_50030501_85_dialog_content = "Pero mi herida es demasiado grave para seguir luchando...",
  ui_story_5003_50030501_X85_dialog_content = "Es hora de que muera.",
  ui_story_5003_50030501_86_dialog_content = "Hiiro, después de que muera, toma mi espada... Se convertirá en una verdadera Espada Sakae.",
  ui_story_5003_50030501_87_dialog_content = "Llamas abrasadoras y la sangre de los Sakae... harán que esta espada sea extre. poderosa. Esta espada Sakae...",
  ui_story_5003_50030501_88_dialog_content = "Te hará muy poderosa. Te otorgará el poder de derrotar a los Eclipsites.",
  ui_story_5003_50030501_89_dialog_content = "Espero que puedas ver tu gran futuro en la Espada Sakae.",
  ui_story_5003_50030501_90_dialog_content = "El Maestro esperaba que pudiera ver el futuro en la Espada Sakae.",
  ui_story_5003_50030501_91_dialog_content = "Pero no sabía qué era este \"futuro\".",
  ui_story_5003_50030501_92_dialog_content = "No entendí hasta que te vi.",
  ui_story_5003_50030501_93_dialog_content = "¿Qué quieres decir con \"hasta que me viste\"?",
  ui_story_5003_50030501_94_dialog_content = "Como tú, regresé a Montaña Nube por odio.",
  ui_story_5003_50030501_95_dialog_content = "Pero ahora lo sé todo.",
  ui_story_5003_50030501_96_dialog_content = "El objeto sellado mantiene la barrera que protege Montaña Nube. Todos murieron protegiendo Montaña Nube.",
  ui_story_5003_50030501_97_dialog_content = "Entonces, no puedo dejar que rompas el sello y dest. lo que hay allí.",
  ui_story_5003_50030501_98_dialog_content = "Pero nunca te mataría.",
  ui_story_5003_50030501_102_dialog_content = "Reconozco tu técnica. Somos de la misma escuela.",
  ui_story_5003_50030501_103_dialog_content = "...",
  ui_story_5003_50030501_104_dialog_content = "¡Padre! ¿Me aceptará realmente el Sakae Dojo?",
  ui_story_5003_50030501_105_dialog_content = "¡Por supuesto! ¡A partir de la sem. que viene, serás discípulo del Sakae Dojo!",
  ui_story_5003_50030501_106_dialog_content = "¡La fam. Sakae es increíble! Protegen todo Montaña Nube. ¡Asegúrate de estudiar mucho desp. de unirte a ellos!",
  ui_story_5003_50030501_107_dialog_content = "¡Está bien, padre! ¡Haré lo mejor que pueda!",
  ui_story_5003_50030501_108_dialog_content = "Ha salido el sol. Es hora de que vaya a Montaña Nube. Te espero en el dojo...",
  ui_story_5003_50030501_109_dialog_content = "Bueno, salió el sol. Es hora de que me vaya.",
  ui_story_5003_50030501_X109_dialog_content = "Mi presencia aquí afectará la estab. del sello, por lo que nunca debo regresar a Montaña Nube.",
  ui_story_5003_50030501_X110_dialog_content = "Espero que nadie descubra nunca lo que está sellado aquí y que Montaña Nube final. conocerá la paz.",
  ui_story_5003_50030501_X111_dialog_content = "Si alguien más busca romper el sello, primero tendrá que tomar mi sangre.",
  ui_story_5003_50030501_X112_dialog_content = "¿Qué hay de mí...?",
  ui_story_5003_50030501_X113_dialog_content = "Puedes intentar sacarme sangre, cuantas veces quieras.",
  ui_story_5003_50030501_X114_dialog_content = "Pero como somos discípulos del Sakae Dojo... Solo lo consideraré \"combate\".",
  ui_story_5003_50030501_110_dialog_content = "Mmm... Parece que Sanki no quiere venir a despedirte.",
  ui_story_5003_50030501_111_dialog_content = "Está bien, no esperaba que lo hiciera.",
  ui_story_5003_50030501_112_dialog_content = "Le enseñé una dura lección con la esperanza de que renun. a su venganza, así que no puedo culparlo por guardar rencor en su corazón...",
  ui_story_5003_50030501_113_dialog_content = "No te preocupes. No creo que te odie.",
  ui_story_5003_50030501_S113_dialog_content = "El día que se enteró de la hab. secreta debajo del hotel... Había planeado proteger la entrada con mi vida.",
  ui_story_5003_50030501_S114_dialog_content = "Pero de repente dejó su arma y dejó de intentar entrar por la fuerza.",
  ui_story_5003_50030501_S115_dialog_content = "Después de eso, comenzó a deambular por aquí, preguntando const. cómo iban las cosas en el hotel.",
  ui_story_5003_50030501_S116_dialog_content = "Poco a poco, se fue abriendo a mí sobre su vida e incluso ayudaría a Tweety con sus quehaceres.",
  ui_story_5003_50030501_S117_dialog_content = "Cuando le dije que no quedaban descen. de la Familia Sakura y que el sello ya no podía romperse...",
  ui_story_5003_50030501_S118_dialog_content = "Lo vi dar un suspiro de alivio.",
  ui_story_5003_50030501_S119_dialog_content = "En ese momento, de repente sentí que tal vez él también nec. una razón para renunciar a su camino de venganza.",
  ui_story_5003_50030501_S120_dialog_content = "Le oculté tu existencia y no le dije el secreto del sello. Todo fue mi culpa.",
  ui_story_5003_50030501_S121_dialog_content = "Sé que solo querías proteger el secreto del sello. No es culpa de nadie.",
  ui_story_5003_50030501_114_dialog_content = "Abuedita, Sanki quiede sumedgirse en las aguas tedmales. Le dije que aún no estaba disto, pero sadtó para limpiadlo él mismo.",
  ui_story_5003_50030501_115_dialog_content = "Samki sostenía un montón de espadas cuando sadtó...",
  ui_story_5003_50030501_116_dialog_content = "Jeje, creo que solo quiere limpiarlos. Pronto saldrá con ellos.",
  ui_story_5003_50030501_117_dialog_content = "Es un buen niño con un buen corazón, y se preo. por la Montaña Nube, pero su vida no ha sido fácil y su mente está un poco confundida.",
  ui_story_5003_50030501_S122_dialog_content = "Nunca creí que real. nos haría daño.",
  ui_story_5003_50030501_118_dialog_content = "Aunque tengo fe en tu juicio, espero que nunca más te veas obligado a enfrentar un asunto tan peligroso solo.",
  ui_story_5003_50030501_119_dialog_content = "Tweety, Taki y yo—si alguna vez necesitas hablar, tienes amigos en los que puedes confiar.",
  ui_story_5003_50030501_120_dialog_content = "En cuanto a Sanki, deb. hablar con él sobre sus planes. Me preocupa que después que ter. las vacac. de Tweety, el hotel se quede corto de personal.",
  ui_story_5003_50030501_121_dialog_content = "Quizás Sanki pueda quedarse aquí y ayudar con el hotel.",
  ui_story_5003_50030501_122_dialog_content = "No te preocupes si vuelve a colarse en el dojo. Si pasa algo, la Espada Sakae me lo hará saber.",
  ui_story_5003_50030501_123_dialog_content = "Muy bien, hijo mío. No te preocupes.",
  ui_story_5003_50030501_124_dialog_content = "Bueno, nunca esperé que trajeras tanto drama contigo...",
  ui_story_5003_50030501_125_dialog_content = "Señor Taki, ¿qué edstá habdando?",
  ui_story_5003_50030501_126_dialog_content = "No, no me hagas caso. Solo estoy de vacac.",
  ui_story_5003_50030501_127_dialog_content = "Adiós.",
  ui_story_5003_50030501_128_dialog_content = "¿¿El señod Taki de fue antes que Hiido??",
  ui_story_5003_50030501_129_dialog_content = "Creo que va en la misma dirección que antes. Se dirige a Calle Spa.",
  ui_story_5003_50030501_130_dialog_content = "¿Quizá se ha ido por negocios, como de costumbre?",
  ui_story_5003_50030501_131_dialog_content = "¡Ciedto! ¡Suena como éd!",
  ui_story_5003_50030501_132_dialog_content = "Se está haciendo tarde. Yo también debería irme.",
  ui_story_5003_50030501_133_dialog_content = "Cuídense, todos.",
  ui_story_5003_50030501_134_dialog_content = "¡Oye! ¡Hiiro!",
  ui_story_5003_50030501_135_dialog_content = "¿No quieres tu Espada Sakae?",
  ui_story_5003_50030501_136_dialog_content = "Mi Espada Sakae nunca se aparta de mi lado. No entiendo de qué estás hablando.",
  ui_story_5003_50030501_137_dialog_content = "Tengo siete de ellas aquí. ¿No las quieres?",
  ui_story_5003_50030501_138_dialog_content = "Claro que no. ¿Cómo podría tomar sus Espadas Sakae?",
  ui_story_5003_50030501_139_dialog_content = "<size=30>\"Espero que puedas ver tu gran futuro en la Espada Sakae\"...</size>",
  ui_story_5003_50030501_140_dialog_content = "¿Eh? ¿Qué dijiste?",
  ui_story_5003_50030501_141_dialog_content = "Nada, estaba hablando solo.",
  ui_story_5003_50030501_142_dialog_content = "Sanki, mi compañero discípulo, debes cuidar el dojo con la abuela.",
  ui_story_5003_50030501_143_dialog_content = "Yo...",
  ui_story_5003_50030501_144_dialog_content = "Confío en ti.",
  ui_story_5003_50030501_145_dialog_content = "¡Cómo sea! Si no quieres las espadas, ¡olvídalo!",
  ui_story_5003_50030501_146_dialog_content = "Si quieres protegerlo, ¡solo protégelo tú misma! De todos modos, ¡todo ha terminado para mí!",
  ui_story_5003_50030501_147_dialog_content = "¡Adiós!",
  ui_story_5003_50030501_148_dialog_content = "Este chico...",
  ui_story_5003_50030501_149_dialog_content = "Yo diría que su mente está más que un poco confundida...",
  ui_story_5003_50030501_150_dialog_content = "Comandante Hiiro, PlayerName suele llamar tsundere a este tipo de persona.",
  ui_story_5003_50030501_151_dialog_content = "Vice, ¡no me cambies de tema de repente!",
  ui_story_5003_50030501_152_dialog_content = "Vice, PlayerName...",
  ui_story_5003_50030501_153_dialog_content = "¡Lo siento, comandante! ¡Sabemos que este no es el momento adecuado para bromear!",
  ui_story_5003_50030501_154_dialog_content = "Eso no es lo que iba a decir.",
  ui_story_5003_50030501_155_dialog_content = "Gracias por tu ayuda y fe en mi. Vamos. Deberíamos regresar.",
  ui_story_5003_50030501_156_dialog_content = "¡Muy bien, Soroz listo para moverse!",
  ui_story_5003_50030501_157_dialog_content = "Buen viaje, hijos míos.",
  ui_story_5003_50030501_158_dialog_content = "¡Adiós! ¡No odviden enviadnos una cadta atavés de Unión de Mensajedía!",
  ui_story_5003_50030501_159_dialog_content = "Por supuesto, tendré a alguien de Unión de Mensajería para que les envíe cartas.",
  ui_story_5003_50030501_160_dialog_content = "Adiós, Montaña Nube."
}
return config
